#include <vector>
#include <array>
#include <iostream>
#include <chrono>
using namespace std;
using Row=vector<pair<int,int>>;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int m,n;cin>>m>>n;vector<Row>P(n);vector<array<int,4>>B(n);vector<array<int,4>>cons;auto start=chrono::steady_clock::now();for(int r=0;r<m;r++){int z;cin>>z;Row a;for(int j=0;j<z;j++){int k,v;cin>>k>>v;v=(v%5+5)%5;if(v)a.emplace_back(k,v);}array<int,4>b;for(int&v:b)cin>>v;while(!a.empty()){int k=a[0].first;if(P[k].empty()){int u=1;while((u*a[0].second)%5!=1)u++;for(auto &e:a)e.second=e.second*u%5;for(int&v:b)v=v*u%5;P[k]=a;B[k]=b;break;}int c=a[0].second;Row q;int i=0,j=0;while(i<(int)a.size()||j<(int)P[k].size()){int key;if(j==(int)P[k].size()||(i<(int)a.size()&&a[i].first<P[k][j].first))key=a[i].first;else key=P[k][j].first;int v=0;if(i<(int)a.size()&&a[i].first==key){v+=a[i].second;i++;}if(j<(int)P[k].size()&&P[k][j].first==key){v-=c*P[k][j].second;j++;}v=(v%5+5)%5;if(v)q.emplace_back(key,v);}a.swap(q);for(int j=0;j<4;j++)b[j]=(b[j]-c*B[k][j]%5+5)%5;}if(a.empty()){bool nz=false;for(int v:b)nz|=v!=0;if(nz)cons.push_back(b);}if(chrono::duration<double>(chrono::steady_clock::now()-start).count()>6){cout<<"budget\n";return 0;}}array<int,4>t{};bool found=false;for(int k=0;k<256&&!found;k++){int v=k;for(int i=0;i<4;i++){t[i]=1+v%4;v/=4;}bool good=true;for(auto b:cons){int s=0;for(int i=0;i<4;i++)s+=b[i]*t[i];if(s%5){good=false;break;}}if(good)found=true;}if(!found){cout<<"none\n";return 0;}vector<int>x(n);for(int k=n-1;k>=0;k--)if(!P[k].empty()){int v=0;for(int i=0;i<4;i++)v+=B[k][i]*t[i];for(auto [j,c]:P[k])if(j!=k)v-=c*x[j];x[k]=(v%5+5)%5;}cout<<"positive\n";for(int v:t)cout<<v<<' ';cout<<'\n';for(int v:x)cout<<v<<' ';cout<<'\n';}
